#include <iostream>
#include <string>
using namespace std;

int main() {
    int fish;
    string name;
    cin >> fish;
    cin.ignore();
    getline(cin, name);
    cout << "小鱼干 " << fish << " 条" << endl;
    cout << "名字是 " << name << endl;
    return 0;
}
